#!/usr/bin/env node
// shot.js: drive a private headless Chrome over the DevTools protocol. No packages needed.
//
//   node shot.js --url http://127.0.0.1:8765/index.html --out page.png
//   node shot.js --url ... --selector "#fig-ring" --out ring.png --width 390 --height 800 --mobile
//   node shot.js --url ... --do "click:#play" --do "wait:800" --do "eval:PETCT.game.state.phase" --out after.png
//
// Options
//   --url URL            page to open (required)
//   --out FILE           final screenshot (optional)
//   --selector CSS       scroll this element into view and crop the final screenshot to it
//   --width N --height N viewport in CSS pixels (default 1280 x 800)
//   --dpr N              device pixel ratio (default 1)
//   --mobile             emulate a touch phone
//   --reduced-motion     emulate prefers-reduced-motion: reduce
//   --wait MS            settle time after load (default 800)
//   --full               capture the whole page height instead of the viewport
//   --fail-on-error      exit 1 when the page logged an error
//   --do ACTION          repeatable, run in order after load:
//        eval:JS | wait:MS | click:CSS | key:NAME | keydown:NAME | keyup:NAME | scroll:CSS | shot:FILE[@CSS]
//
// Prints one JSON object: { ok, url, errors[], console[], results[], shots[] }.
'use strict';

const { spawn } = require('node:child_process');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

function parseArgs(argv)
