cat > build/gen.js <<'EOF'
const fs=require('fs'),path=require('path');
const out=path.resolve(__dirname,'..');
const P={
 a:{label:'A · Bricolage Grotesque + Figtree',
  faces:[['Bricolage Grotesque','bricolage-grotesque-latin-opsz-normal.woff2','200 800'],['Figtree','figtree-latin-wght-normal.woff2','300 900'],['Figtree','figtree-latin-wght-italic.woff2','300 900','italic']],
  d:"'Bricolage Grotesque', 'Segoe UI', system-ui, sans-serif", b:"'Figtree', 'Segoe UI', system-ui, sans-serif",
  css:`h1{font-weight:700;font-size:76px;letter-spacing:-0.025em;line-height:1.0;font-variation-settings:'opsz' 96}
       h2{font-weight:600;font-size:34px;letter-spacing:-0.01em;font-variation-settings:'opsz' 40}
       p{font-size:18.5px;line-height:1.62;font-weight:400}
       .nums{font-family:var(--b);font-weight:600;font-size:22px}
       .btn{font-weight:700}`},
 b:{label:'B · Fraunces + Source Sans 3',
  faces:[['Fraunces','fraunces-latin-opsz-normal.woff2','100 900'],['Source Sans 3','source-sans-3-latin-wght-normal.woff2','200 900'],['Source Sans 3','source-sans-3-latin-wght-italic.woff2','200 900','italic']],
  d:"'Fraunces', Georgia, 'Times New Roman', serif", b:"'Source Sans 3', 'Segoe UI', system-ui, sans-serif",
  css:`h1{font-weight:500;font-size:78px;letter-spacing:-0.02em;line-height:1.02;font-variation-settings:'opsz' 144}
       h2{font-weight:500;font-size:35px;font-variation-settings:'opsz' 48}
       p{font-size:19.5px;line-height:1.6;font-weight:400}
       .nums{font-family:var(--b);font-weight:600;font-size:23px}
       .btn{font-weight:600;font-size:16.5px}.cap{font-size:15.5px}.eyebrow{font-size:14px}`},
 c:{label:'C · Oxanium + IBM Plex Sans',
  faces:[['Oxanium','oxanium-latin-wght-normal.woff2','200 800'],['IBM Plex Sans','ibm-plex-sans-latin-wght-normal.woff2','100 700'],['IBM Plex Sans','ibm-plex-sans-latin-wght-italic.woff2','100 700','italic']],
  d:"'Oxanium', 'Bahnschrift', 'Segoe UI', sans-serif", b:"'IBM Plex Sans', 'Segoe UI', system-ui, sans-serif",
  css:`h1{font-weight:600;font-size:70px;letter-spacing:-0.01em;line-height:1.05}
       h2{font-weight:600;font-size:32px;letter-spacing:0.01em}
       p{font-size:18px;line-height:1.65;font-weight:400}
       .nums{font-family:var(--d);font-weight:500;font-size:24px;letter-spacing:0.02em}
       .btn{font-family:var(--d);font-weight:600;letter-spacing:0.04em;text-transform:uppercase;font-size:14.5px}`}
};
for(const [k,p] of Object.entries(P)){
 const ff=p.faces.map(f=>`@font-face{font-family:'${f[0]}';src:url('dl/${f[1]}') format('woff2');font-weight:${f[2]};font-style:${f[3]||'normal'};font-display:block}`).join('\n');
 const html=`<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Specimen ${k.toUpperCase()}</title><style>
${ff}
:root{--d:${p.d};--b:${p.b};--bg:#0a0f1e;--fg:#d5dae3;--mute:#8d96a8;--line:#1e2740;--acc:#ff9f43}
*{box-sizing:border-box}html,body{margin:0;background:var(--bg);color:var(--fg)}
body{font-family:var(--b);padding:44px 64px;-webkit-font-smoothing:antialiased}
.eyebrow{font-size:13px;letter-spacing:.14em;text-transform:uppercase;color:var(--mute);font-weight:600;margin:0 0 22px}
h1,h2{font-family:var(--d);color:#f1f3f7;margin:0}
h1{margin-bottom:34px}
h2{margin-bottom:14px}
h2 .n{color:var(--acc)}
p{max-width:64ch;margin:0 0 26px}
.nums{font-variant-numeric:tabular-nums;color:#f1f3f7;margin:0 0 30px;padding:14px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);max-width:64ch}
.nums .s{color:var(--acc);margin:0 .5em}
.nums .u{color:var(--mute);font-weight:400}
.row{display:flex;align-items:center;gap:26px}
.btn{font-family:var(--b);font-size:15.5px;color:var(--bg);background:var(--acc);border:0;border-radius:6px;padding:10px 18px}
.cap{font-size:14.5px;color:var(--mute);font-style:italic}
.cap b{font-style:normal;font-weight:600;color:var(--fg)}
${p.css}
</style></head><body>
<div class="eyebrow">${p.label}</div>
<h1>Seeing inside, two ways</h1>
<h2><span class="n">2 ·</span> The science</h2>
<p>A PET/CT scanner is two machines sharing one bed. The CT half sends X-rays through the body to map its anatomy. The PET half listens for pairs of gamma rays released when a radioactive tracer decays, showing where cells are busiest. Laid over each other, the two pictures reveal both where things are and what they are doing.</p>
<div class="nums">511 <span class="u">keV</span><span class="s">·</span>109.8 <span class="u">min</span><span class="s">·</span>&minus;1000 <span class="u">HU</span><span class="s">·</span>1971</div>
<div class="row"><button class="btn">Start the scan</button><span class="cap"><b>Fig. 3</b> &nbsp;Two gamma rays leave in opposite directions and strike the detector ring.</span></div>
<div id="t" style="position:absolute;left:-9999px;font-variant-numeric:tabular-nums"></div>
</body></html>`;
 fs.writeFileSync(path.join(out,`specimen-${k}.html`),html);
}
EOF
