 display:fam('Oxanium','oxanium',[file('oxanium','5.3.0','wght-normal','200-800','normal')],'wght axis only (200-800). Figures tabular by default (measured).'),
 body:fam('IBM Plex Sans','ibm-plex-sans',[file('ibm-plex-sans','5.3.0','wght-normal','100-700','normal'),file('ibm-plex-sans','5.3.0','wght-italic','100-700','italic')],'wght-only file (width axis not included). Figures tabular by default (measured). Italic optional but large (50,184 bytes).')}
];
